import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"艮","description":"東坡易傳 - 艮","frontmatter":{"title":"艮","description":"東坡易傳 - 艮"},"headers":[],"relativePath":"classics/dongpo/053.md","filePath":"classics/dongpo/053.md"}'),o={name:"classics/dongpo/053.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="艮" tabindex="-1">艮 <a class="header-anchor" href="#艮" aria-label="Permalink to “艮”">​</a></h1><p>“艮”其背，不獲其身；行其庭，不見其人，無咎。</p><p>《彖》曰：“艮”，止也；時止則止，時行則行，動靜不失其時，其道光明。“艮其止”，止其所也；上下敵應，不相與也；是以“不獲其身，行其庭，不見其人，無咎”也。</p><p>所貴於聖人者，非貴其靜而不交於物，貴其與物皆入于吉兇之域而不亂也。故夫“艮”，聖人將有所施之。“艮，止也”，止與靜相近而不同，方其動而止之，則靜之始也；方其靜而止之，則動之先也，故曰：“時止則止，時行則行，動靜不失其時，其道光明。”此言“艮”之得其所施者也。施之於天下之至動，是以為“頤”；施之於天下之至健，是以為“大畜”。今夫兼山“艮”，是施之於“背”而已，“背”固已止矣，“艮”何加焉？所以為柅者、為輪也；所以為防者、為水也。今也不然，為輿、為枙，為山、為防，不亦近於固歟？故曰：“艮其止，止其所也。”此所以“不獲其身”也。“上下敵應，不相與也”，此所以“行其庭，不見其人”也。物各止於其所，是果能止也哉？背止於身，身與之動而背不知也，今我施止於物之所，止有大於是物者。則挾而與之趨矣，我焉得知之？故曰“艮其背，不獲其身”，其庭未嘗無人也，有六人焉①，敵應而不相與，則如無人。是道也，非向之所謂光明者也，以為無咎而已。</p><p>【校注】 ① 有六人焉：《蘇氏易傳》無“六”字。</p><p>象曰：兼山，“艮”；君子以思不出其位。</p><p>初六：艮其趾，無咎，利永貞。象曰：“艮其趾”，未失正也。</p><p>六二：艮其腓，不拯其隨，其心不快。象曰：“不拯其隨”，未退聽也。</p><p>自“趾”而上，至於“輔”，當其處者有其德，與“鹹”一也。“鹹”以上六為“輔”，而五為“脢”，“艮”之“輔”在五，而“脢”不取，何也？“脢”則“背”也，“艮”皆取於動者而已。“艮”則何為皆取於動者也？曰：卦合而觀之，見兩“艮”焉；見其施“艮”於止，故取其體之靜者而配之，曰“艮其背”。爻別而觀之，不見“艮”之所施，而各見其所遇之位；位有不同，而吉、兇、悔、吝生焉，故取其體之動者而不取其靜，以為其靜者已見於卦矣。上止而用下，下止而聽於上，此“艮”之正也。趾能動而聽於腓者也，“艮其趾”，不害於腓之動也；趾不自動而已，止而聽其上，上止則止，上行則行，此“艮”之正者也，故“利永貞”。腓能動而不聽於股者也，或曰“鹹其股，執其隨”，隨者股之德也，故謂“股為隨”。“艮其腓”，則股雖欲行而不能矣，下止而不聽於上，上雖有憂患而莫之救，則上之所不快也，以是為失其正矣，故曰：“艮其趾，未失正也。”</p><p>九三：艮其限，列其夤，厲薰心。象曰：“艮其限”，危薰心也。</p><p>三不“艮於股”而“艮於限”，亦取諸動者也。“限”者，上下之際，所以俯仰之節也。“夤”者，自上而屬於下者也。“艮”於下之極，則其自上而下者絕矣；上下絕，心之憂也。心在六四，故憂之；及心也，謂之“薰”。</p><p>六四：艮其身，無咎。象曰：“艮其身”，止諸躬也。</p><p>“鹹”之九四曰：“朋從爾思。”則四者，心之所在也。施之於一體，則“艮”止於所施，所不施者不及也。施之於心，則無所不及矣，故曰“艮其身”。“艮”得其要，故“無咎”。</p><p>六五：艮其輔，言有序，悔亡。象曰：“艮其輔“，以中正也。</p><p>口欲止，言欲寡。</p><p>上九：敦艮，吉。象曰：“敦艮”之“吉“，以厚終也。</p><p>“敦”，益也。“艮”至於輔，極矣；而又止之，故曰“敦艮”。梏者不忘釋，痿者不忘起，物之情也。在止之極而不忘於動，非天下之至厚，其孰能之？</p>',17)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
